'use client'
import { useControllableSignal, useSignals } from '@cascivo/core'
import styles from './swap.module.css'

export type SwapMode = 'rotate' | 'flip'

export interface SwapProps {
  on: React.ReactNode
  off: React.ReactNode
  /**
   * Whether the control is checked (controlled).
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  checked?: boolean
  /** Called with the new checked state when the swap is toggled. */
  onValueChange?: (checked: boolean) => void
  mode?: SwapMode
  /**
   * Invisible accessible name. The catalog convention (see the item-identity table in
   * `docs/AI-RULES.md`); `aria-label` is accepted as an alias for the DOM spelling.
   */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
  'aria-label'?: string
  className?: string
}

export function Swap({
  on,
  off,
  checked = false,
  onValueChange,
  mode = 'rotate',
  className,
  ariaLabel,
  label,
  ...aria
}: SwapProps) {
  useSignals()
  // Controlled mirror goes through the shared primitive: a bare `sig.value = prop` in render
  // notifies the previous render's subscriptions, which React 19 reports as a setState during
  // render (2026-08-08 report A). The primitive skips the write when the value is unchanged.
  const [isChecked] = useControllableSignal<boolean>({ value: checked })

  function handleClick() {
    const next = !isChecked.value
    onValueChange?.(next)
  }

  return (
    <button
      type="button"
      role="switch"
      aria-checked={isChecked.value}
      className={[styles.swap, className].filter(Boolean).join(' ')}
      data-checked={isChecked.value || undefined}
      data-mode={mode}
      onClick={handleClick}
      {...aria}
      {...((ariaLabel ?? label) !== undefined ? { 'aria-label': ariaLabel ?? label } : {})}
    >
      <span className={styles.on} aria-hidden="true">
        {on}
      </span>
      <span className={styles.off} aria-hidden="true">
        {off}
      </span>
    </button>
  )
}

@layer cascivo.component {
  .swap {
    display: inline-grid;
    grid-template-areas: 'swap';
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    position: relative;
    overflow: hidden;
  }

  .swap:focus-visible {
    outline: var(--cascivo-ring-width) solid var(--cascivo-ring-color);
    outline-offset: 2px;
    border-radius: var(--cascivo-radius-control);
  }

  .on,
  .off {
    grid-area: swap;
    display: flex;
    align-items: center;
    justify-content: center;
    transition-property: transform, opacity;
    transition-duration: var(--cascivo-duration-200);
    transition-timing-function: var(--cascivo-ease-out);
  }

  .swap[data-mode='rotate'] .on {
    transform: rotate(0deg);
    opacity: 1;
  }
  .swap[data-mode='rotate'] .off {
    transform: rotate(-90deg);
    opacity: 0;
  }
  .swap[data-mode='rotate'][data-checked] .on {
    transform: rotate(90deg);
    opacity: 0;
  }
  .swap[data-mode='rotate'][data-checked] .off {
    transform: rotate(0deg);
    opacity: 1;
  }

  .swap[data-mode='flip'] .on {
    transform: rotateY(0deg);
    opacity: 1;
  }
  .swap[data-mode='flip'] .off {
    transform: rotateY(180deg);
    opacity: 0;
  }
  .swap[data-mode='flip'][data-checked] .on {
    transform: rotateY(-180deg);
    opacity: 0;
  }
  .swap[data-mode='flip'][data-checked] .off {
    transform: rotateY(0deg);
    opacity: 1;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Swap',
  description: 'Animated toggle between two icon/content states with rotate or flip transition',
  category: 'inputs',
  // The component is a toggle: with JS off the button renders but cannot swap, so the
  // 'off' child is all you ever see. Interactivity is the feature, not a polish layer.
  clientJs: 'required',
  states: ['unchecked', 'checked'],
  variants: ['rotate', 'flip'],
  sizes: [],
  props: [
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description:
        'Invisible accessible name. The catalog convention; `aria-label` is accepted as an alias for the DOM spelling.',
    },
    {
      name: 'on',
      description: 'Content shown in the active (on) state.',
      type: 'React.ReactNode',
      required: true,
    },
    {
      name: 'off',
      description: 'Content shown in the inactive (off) state.',
      type: 'React.ReactNode',
      required: true,
    },
    {
      name: 'checked',
      description: 'Whether the control is checked (controlled).',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'onValueChange',
      description: 'Called with the new checked state when the swap is toggled.',
      type: '(checked: boolean) => void',
      required: false,
    },
    {
      name: 'mode',
      description: "Transition between states ('rotate' | 'flip').",
      type: "'rotate' | 'flip'",
      required: false,
      default: 'rotate',
    },
    {
      name: 'aria-label',
      description: 'Accessible label used when no visible label is present.',
      type: 'string',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-ring-width',
    '--cascivo-ring-color',
    '--cascivo-radius-control',
    '--cascivo-ease-out',
  ],
  accessibility: {
    role: 'switch',
    wcag: '2.2-AA',
    keyboard: ['Space', 'Enter'],
  },
  examples: [
    {
      title: 'Theme toggle (rotate)',
      code: '<Swap on={<SunIcon />} off={<MoonIcon />} mode="rotate" aria-label="Toggle theme" />',
      description: 'Sun/moon icon that rotates between two states',
    },
    {
      title: 'Flip mode',
      code: '<Swap on={<HeartFilledIcon />} off={<HeartIcon />} mode="flip" aria-label="Favorite" />',
      description: 'Heart icon that flips to filled on activation',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['toggle', 'icon', 'animate', 'switch', 'flip', 'rotate'],
  intent: {
    whenToUse: [
      'Theme toggles where an icon animates between two states (sun/moon)',
      'Favorite or bookmark toggles that flip between outlined and filled icons',
      'Any scenario where exactly two icons swap places with a transition',
    ],
    whenNotToUse: [
      'Form toggles with a visible label — use Toggle',
      'Checkbox-style inputs that are part of a submitted form — use Checkbox',
      'When a text label must always be visible alongside the control',
    ],
    antiPatterns: [
      {
        bad: '<Swap on="Enable" off="Disable" /> (text content)',
        good: '<Toggle label="Enable notifications" />',
        why: 'Swap is designed for icon transitions; for labeled on/off controls use Toggle',
      },
    ],
    related: [
      {
        name: 'Toggle',
        relationship: 'alternative',
        reason: 'Use when a visible text label is required alongside the switch control',
      },
      {
        name: 'Checkbox',
        relationship: 'alternative',
        reason: 'Use for form selections that are submitted rather than applied immediately',
      },
    ],
    a11yRationale:
      'Renders a <button role="switch"> with aria-checked reflecting state. Both on/off slots are aria-hidden so screen readers announce the button state, not the icon content.',
    flexibility: [
      {
        area: 'content',
        level: 'flexible',
        note: 'on/off slots accept any ReactNode — icons, text, images',
      },
      {
        area: 'animation mode',
        level: 'flexible',
        note: 'rotate (default) or flip — choose based on the visual metaphor of the icons',
      },
    ],
  },
}
